SELECT 'gongkao', '增长率概述', 'kp-xc-data-growth-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"增长率概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"增长率是资料分析中题量最大的概念，约 8 题。核心公式：增长率 = 增长量/基期量 = (现期-基期)/基期。包含六个子类型。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","content":[{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"子类"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长率计算：求增长率"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长量计算：求增长的绝对量"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长比较：比较大小"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"间隔增长：跨两期增长"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"年均增长：多年平均"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"混合增长：整体由部分组成"}]}]}]}]},{"type":"column","content":[{"type":"paragraph","content":[{"type":"text","text":"核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"r = 增长量/基期"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长量 = 现期×r/(1+r)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"大小比较"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"r = r1+r2+r1×r2"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"末期=初期×(1+r)^n"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"整体居中偏量大"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心公式"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长率 r = (现期 - 基期) / 基期 = 增长量 / 基期"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"基期 = 现期 / (1 + r)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"增长量 = 现期 - 基期 = 现期 × r / (1 + r)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"间隔增长率 r = r1 + r2 + r1 × r2"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"年均增长率：末期 = 初期 × (1 + r)^n"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、速算技巧"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"截位直除法：选项差距大时，分子分母截取前 2-3 位"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"特殊分数法：r = 1/n 时，增长量 = 现期/(n+1)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"混合增长率：十字交叉法，整体居中偏量大"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「增长了」vs「增长到」— 增长了是求增长率，增长到是求现期值"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"百分数 vs 百分点 — 增长率用百分数，增长率之差用百分点"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"间隔增长率公式不要记错 — r = r1 + r2 + r1×r2，不是 r1+r2"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"增长率是资料分析的基础，必须熟练掌握。建议先背公式，再做 20 题巩固。"}]}]}]}]}$$ AS jsonb), NULL, '增长率概述：增长率计算、增长量计算、间隔增长、年均增长、混合增长。', category_node.id, CAST('["资料分析", "增长率"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_growth", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
